-- Safe room lifecycle RPCs; clients never assign ownership or roles directly.
create or replace function public.join_public_room(target_room uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from rooms where id=target_room and not is_private and kind in ('interest','custom')) then raise exception 'Room is not joinable'; end if; insert into room_members(room_id,user_id,role) values(target_room,auth.uid(),'member') on conflict(room_id,user_id) do nothing; end $$;
create or replace function public.leave_room(target_room uuid) returns void language plpgsql security definer set search_path=public as $$ begin delete from room_members where room_id=target_room and user_id=auth.uid() and role='member'; end $$;
create or replace function public.create_room(room_name text, room_topic text, private_room boolean) returns uuid language plpgsql security definer set search_path=public as $$ declare new_id uuid; room_slug text; begin if char_length(trim(room_name)) not between 3 and 60 or char_length(coalesce(room_topic,'')) > 240 then raise exception 'Invalid room details'; end if; room_slug:=lower(regexp_replace(trim(room_name),'[^a-zA-Z0-9]+','-','g')); insert into rooms(slug,name,topic,kind,is_private,created_by) values(room_slug,trim(room_name),nullif(trim(room_topic),''),'custom',private_room,auth.uid()) returning id into new_id; insert into room_members(room_id,user_id,role) values(new_id,auth.uid(),'owner'); return new_id; end $$;
revoke all on function public.join_public_room(uuid), public.leave_room(uuid), public.create_room(text,text,boolean) from public; grant execute on function public.join_public_room(uuid), public.leave_room(uuid), public.create_room(text,text,boolean) to authenticated;
